 return f'<section class="page-hero{layout}"><div class="wrap hero-grid"><div><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lead">{desc}</p><div class="actions">{link(url,action)}{link("/services.html","Explore services","btn ghost")}</div></div>{visual}</div></section>'
