 body+=section('SCOPE OF SERVICE','Practical help.<br>Clearly defined.','Each engagement starts with a scope matched to your environment.','<div class="feature-grid">'+''.join('<article><span class="ico">'+icon(feature_icon)+'</span><h3>'+x.split('|')[0]+'</h3><p>'+x.split('|')[1]+'</p></article>' for x, feature_icon in zip(features, service_feature_icons[slug], strict=True))+'</div>')
